import { useState, useRef, useEffect } from "react";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";

// ─── Letterhead: Official DataNest BD A4 (JPEG base64) ────────
const LH = "data:image/jpeg;base64,";

// ─── FIX-5: Safe BDT formatter — en-BD may be unsupported in ──
// ─── older Android WebView / Firefox Android ──────────────────
const fmtBDT = (n) => {
  const num = Number(n);
  if (isNaN(num)) return "0.00";
  const opts = { minimumFractionDigits: 2, maximumFractionDigits: 2 };
  try { return num.toLocaleString("en-BD", opts); }
  catch { return num.toLocaleString("en-US", opts); }
};


