// ─── Print CSS ─────────────────────────────────────────────────
const PRINT_CSS = `@media print {
  .no-print { display: none !important; }
  body { margin: 0; padding: 0; background: #fff !important; }
  #inv-page { box-shadow: none !important; }
}`;

// ─── FIX-1: Content overflow estimator ────────────────────────
// Safe content area = 1408 - 183(top) - 179(bottom) = 1046px
// Each table row ≈ 32px, fixed chrome (meta+BillTo+totals+TC+footer) ≈ 580px
const CONTENT_AREA_PX = 1046;
function willOverflow(itemCount, hasNotes) {
  const fixed = 580 + (hasNotes ? 60 : 0);
  const tableRows = 32 + itemCount * 32; // header + rows
  return (fixed + tableRows) > CONTENT_AREA_PX;
}

