// ─── FIX-3: Prevent scroll-wheel from changing number inputs ──
const noWheel = { onWheel: (e) => e.currentTarget.blur() };

// ─── Field component ───────────────────────────────────────────
function F({ label, value, onChange, ph, type = "text", min }) {
  const extra = type === "number" ? { ...noWheel, min } : {};
  return (
    <div>
      <label style={S.lbl}>{label}</label>
      <input type={type} value={value} placeholder={ph} style={S.inp}
        onChange={(e) => onChange(e.target.value)} {...extra} />
    </div>
  );
}

