// ─── Main App ──────────────────────────────────────────────────
export default function InvoiceGenerator() {
  const getToday = () => new Date().toISOString().slice(0, 10);

  // Number: peek (no increment) on load/reset; consume on download
  const peekNextNum = (type = "invoice") => {
    try {
      const key = type === "quotation" ? "dn_quot_num" : "dn_inv_num";
      const prefix = type === "quotation" ? "QT" : "DN";
      const last = parseInt(localStorage.getItem(key) || "0", 10);
      const n = isNaN(last) ? 1 : last + 1;
      return prefix + "-" + String(n).padStart(4, "0");
    } catch { return type === "quotation" ? "QT-0001" : "DN-0001"; }
  };

  const consumeNum = (numStr, type = "invoice") => {
    try {
      const prefix = type === "quotation" ? "QT-" : "DN-";
      const key    = type === "quotation" ? "dn_quot_num" : "dn_inv_num";
      const n    = parseInt((numStr || "").replace(prefix, ""), 10);
      const last = parseInt(localStorage.getItem(key) || "0", 10);
      if (!isNaN(n) && n > (isNaN(last) ? 0 : last)) {
        localStorage.setItem(key, String(n));
      }
    } catch {}
  };

  const makeBlank = (type = "invoice") => ({
    number: peekNextNum(type), date: getToday(),
    due: "", disc: "0", paymethod: "",
  });

  const [docType, setDocType] = useState("invoice");
  const [inv, setInv]         = useState(makeBlank);
  const [client, setClient]   = useState({ name: "", company: "", address: "", phone: "", email: "" });
  const [items, setItems]     = useState([{ id: 1, desc: "", qty: "1", rate: "", disc: "", note: "" }]);
  const nextId = useRef(2);
  const [notes, setNotes]     = useState("");
  const [paid, setPaid]       = useState(false);
  const [genState, setGen]    = useState("idle");
  const [pdfErr, setPdfErr]   = useState("");

  const viewerRef = useRef(null);
  const [previewScale, setPreviewScale] = useState(1);
  useEffect(() => {
    if (!viewerRef.current) return;
    const ro = new ResizeObserver(entries => {
      const w = entries[0].contentRect.width;
      if (w > 0) setPreviewScale(w / 995);
    });
    ro.observe(viewerRef.current);
    return () => ro.disconnect();
  }, []);

  const si = (k, v) => setInv((p) => ({ ...p, [k]: v }));
  const sc = (k, v) => setClient((p) => ({ ...p, [k]: v }));
  const ui = (i, k, v) => { const a = [...items]; a[i] = { ...a[i], [k]: v }; setItems(a); };
  const switchType = (type) => { setDocType(type); setInv((p) => ({ ...p, number: peekNextNum(type) })); };

  const reset = () => {
    setDocType("invoice");
    setInv(makeBlank("invoice"));
    setClient({ name: "", company: "", address: "", phone: "", email: "" });
    nextId.current = 2;
    setItems([{ id: 1, desc: "", qty: "1", rate: "", disc: "", note: "" }]);
    setNotes(""); setPaid(false); setGen("idle");
  };

  // FIX-6: Hardcoded A4 px — no dependency on browser zoom/DPI
  const downloadPDF = async () => {
    setGen("loading");
    try {
      consumeNum(inv.number, docType);
      const el = document.getElementById("inv-page");
      if (!el) throw new Error("Invoice element not found");

      // Wait for all web fonts to finish loading before capture
      await document.fonts.ready;

      const canvas = await html2canvas(el, {
        scale: 2,
        useCORS: true,
        backgroundColor: "#ffffff",
        logging: false,
        width: 995,
        height: 1408,
        windowWidth: 995,
        windowHeight: 1408,
        foreignObjectRendering: false,
        onclone: (_clonedDoc, clonedEl) => {
          // Remove external font <link> tags from clone — fonts already in browser cache.
          // Prevents html2canvas from re-fetching Google Fonts via CORS (fails on system-font
          // fallbacks like Segoe UI that have no fetchable URL).
          _clonedDoc.querySelectorAll('link[href*="fonts.googleapis.com"], link[href*="fonts.gstatic.com"]')
            .forEach(n => n.remove());
          // Ensure PAID badge (if visible) is fully within capture bounds
          clonedEl.style.overflow = "visible";
        },
      });

      const imgData = canvas.toDataURL("image/jpeg", 0.93);
      const pdf = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
      pdf.addImage(imgData, "JPEG", 0, 0, 210, 297);
      pdf.save("DataNestBD-Invoice-" + (inv.number || "DN-0001") + ".pdf");
      // Auto-advance invoice number so next download gets a fresh number
      si("number", peekNextNum(docType));
      setGen("idle");
    } catch (err) {
      console.error("PDF error:", err);
      setPdfErr(err?.message || String(err));
      setGen("error");
      setTimeout(() => { setGen("idle"); setPdfErr(""); }, 6000);
    }
  };

  const overflow = willOverflow(items.length, !!notes);
  const btnLabel = { idle: "⬇  Download PDF", loading: "⏳  Generating…", error: "⚠  Try Again" };
  const btnColor = { idle: C.navy, loading: "#4B6B9E", error: "#C0392B" };

  return (
    <div style={S.app}>

      {/* Form Panel */}
      <div style={S.panel} className="no-print">
        <div style={S.panelHead}>
          <span style={{ fontSize: 18 }}>📄</span>
          Invoice Builder — DataNest BD
        </div>

        {/* Document Type Toggle */}
        <div style={{ marginBottom: 4 }}>
          <label style={S.lbl}>Document Type</label>
          <div style={{ display: "flex", gap: 6, marginTop: 4 }}>
            {["invoice", "quotation"].map((t) => (
              <button key={t} onClick={() => switchType(t)} style={{
                flex: 1, padding: "7px 0", fontSize: 11, fontWeight: 700,
                border: "1.5px solid " + (docType === t ? C.navy : C.border),
                borderRadius: 6, cursor: "pointer", letterSpacing: 0.4,
                background: docType === t ? C.navy : "#fff",
                color: docType === t ? "#fff" : C.muted,
                textTransform: "uppercase", transition: "all 0.15s",
              }}>
                {t === "invoice" ? "Invoice" : "Quotation"}
              </button>
            ))}
          </div>
        </div>

        <div style={S.sec}>{docType === "quotation" ? "Quotation" : "Invoice"} Details</div>
        <div>
          <label style={S.lbl}>{docType === "quotation" ? "Quotation #" : "Invoice #"}</label>
          <div style={{ ...S.inp, background: "#F0F3F8", color: C.muted, userSelect: "all", cursor: "default", display: "flex", alignItems: "center" }}>
            {inv.number}
          </div>
        </div>
        <F label={docType === "quotation" ? "Quotation Date" : "Invoice Date"} value={inv.date} onChange={(v) => si("date", v)} type="date" />
        <F label="Due Date"       value={inv.due}       onChange={(v) => si("due", v)}       type="date" />
        {/* FIX-2: min="0" prevents negative discount */}
        <F label="Discount (BDT)" value={inv.disc}      onChange={(v) => si("disc", v)}      type="number" ph="0" min="0" />
        <F label="Payment Method" value={inv.paymethod} onChange={(v) => si("paymethod", v)} ph="bKash / Bank Transfer / COD" />

        <div style={S.sec}>Client Info</div>
        <F label="Client Name"  value={client.name}    onChange={(v) => sc("name", v)}    ph="Rahim Ahmed" />
        <F label="Company"      value={client.company} onChange={(v) => sc("company", v)} ph="ABC Traders Ltd." />
        <F label="Address"      value={client.address} onChange={(v) => sc("address", v)} ph="Gulshan-2, Dhaka 1212" />
        <F label="Phone"        value={client.phone}   onChange={(v) => sc("phone", v)}   ph="+8801700-000000" />
        <F label="Email"        value={client.email}   onChange={(v) => sc("email", v)}   ph="client@company.com" />

        <div style={S.sec}>Line Items</div>
        {items.map((item, i) => (
          <div key={item.id ?? i} style={S.itemBox}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
              <span style={{ fontSize: 10, fontWeight: 700, color: C.muted, letterSpacing: 0.5 }}>ITEM {i + 1}</span>
              {items.length > 1 && (
                <button style={S.rmBtn} onClick={() => setItems(items.filter((_, j) => j !== i))}>
                  ✕ Remove
                </button>
              )}
            </div>
            <input style={{ ...S.inp, marginBottom: 6 }} placeholder="Service / Product Description"
              value={item.desc} onChange={(e) => ui(i, "desc", e.target.value)} />
            <input style={{ ...S.inp, marginBottom: 6, fontSize: 11, color: C.muted }} placeholder="Item notes (optional)"
              value={item.note} onChange={(e) => ui(i, "note", e.target.value)} />
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr auto", gap: 6, alignItems: "end" }}>
              <div>
                <label style={{ ...S.lbl, marginTop: 0 }}>Qty</label>
                <input style={S.inp} type="number" min="1" placeholder="1"
                  value={item.qty} onChange={(e) => ui(i, "qty", e.target.value)}
                  onWheel={(e) => e.currentTarget.blur()} />
              </div>
              <div>
                <label style={{ ...S.lbl, marginTop: 0 }}>Rate (BDT)</label>
                <input style={S.inp} type="number" min="0" placeholder="0"
                  value={item.rate} onChange={(e) => ui(i, "rate", e.target.value)}
                  onWheel={(e) => e.currentTarget.blur()} />
              </div>
              <div>
                <label style={{ ...S.lbl, marginTop: 0 }}>Disc (%)</label>
                <input style={S.inp} type="number" min="0" max="100" placeholder="0"
                  value={item.disc} onChange={(e) => ui(i, "disc", e.target.value)}
                  onWheel={(e) => e.currentTarget.blur()} />
              </div>
              <div style={{ paddingBottom: 7, fontSize: 12, fontWeight: 700, color: C.navy, whiteSpace: "nowrap" }}>
                ৳ {fmtBDT(
                  Math.max(0, parseFloat(item.qty)||0) *
                  Math.max(0, parseFloat(item.rate)||0) *
                  (1 - Math.min(100, Math.max(0, parseFloat(item.disc)||0)) / 100)
                )}
              </div>
            </div>
          </div>
        ))}
        <button style={S.addBtn} onClick={() => { const id = nextId.current++; setItems([...items, { id, desc: "", qty: "1", rate: "", disc: "", note: "" }]); }}>
          + Add Item
        </button>

        <div style={S.sec}>Notes</div>
        <textarea value={notes} onChange={(e) => setNotes(e.target.value)}
          placeholder="Payment terms, additional info..."
          style={{ ...S.inp, height: 58, resize: "vertical" }} />

        <div style={{ marginTop: 14, display: "flex", alignItems: "center", gap: 8, marginBottom: 16 }}>
          <input type="checkbox" id="paid" checked={paid} onChange={(e) => setPaid(e.target.checked)}
            style={{ width: 15, height: 15, cursor: "pointer", accentColor: C.green }} />
          <label htmlFor="paid" style={{ fontSize: 12, fontWeight: 700, color: C.navy, cursor: "pointer" }}>
            Mark as PAID
          </label>
        </div>

        {/* FIX-1: Overflow warning shown in panel before download */}
        {overflow && (
          <div style={{
            background: "#FFF8E1", border: "1px solid #F0C040",
            borderRadius: 6, padding: "8px 10px", marginBottom: 10,
            fontSize: 11, color: "#7A5F00", lineHeight: 1.5,
          }}>
            ⚠ <strong>Page overflow detected.</strong> With this many items the content may
            extend past the A4 boundary. Remove items or shorten descriptions before downloading.
          </div>
        )}

        <button onClick={downloadPDF} disabled={genState === "loading"} style={{
          width: "100%", border: "none", borderRadius: 7,
          padding: "10px 0", fontWeight: 700, fontSize: 13,
          cursor: genState === "loading" ? "not-allowed" : "pointer",
          background: btnColor[genState], color: "#fff",
          marginBottom: 8, letterSpacing: 0.3, transition: "background 0.2s",
        }}>
          {btnLabel[genState]}
        </button>

        <button onClick={reset} style={{
          width: "100%", background: "#fff", color: C.navy,
          border: "1.5px solid " + C.border, borderRadius: 7,
          padding: "9px 0", fontWeight: 600, fontSize: 13, cursor: "pointer",
        }}>
          ↺ New Invoice
        </button>

        {genState === "error" && (
          <div style={{ marginTop: 10, fontSize: 11, color: "#C0392B", lineHeight: 1.4, textAlign: "center" }}>
            PDF generation failed. Please try again.
            {pdfErr && <div style={{ marginTop: 4, fontSize: 10, color: "#7A2A1A", wordBreak: "break-all" }}>{pdfErr}</div>}
          </div>
        )}
      </div>

      {/* Invoice Preview — scales to fit available width */}
      <div ref={viewerRef} style={{ flex: 1, minWidth: 0, overflow: "hidden", height: `${Math.round(1408 * previewScale)}px` }}>
        <div style={{ width: 995, transformOrigin: "top left", transform: `scale(${previewScale})` }}>
          <InvoicePreview d={{ inv, client, items, notes, paid, docType }} />
        </div>
      </div>

      <style>{PRINT_CSS}</style>
    </div>
  );
}
